from questions._util import AWESOME, BLUE, IX, RAE, q

PSA = "https://labs.iximiuz.com/challenges/roll-out-pod-security-standards-across-three-namespaces-1be633bd"
SECCOMP = "https://labs.iximiuz.com/challenges/lock-down-container-syscalls-with-seccomp-5c86273c"
DOCKER = "https://labs.iximiuz.com/tutorials/docker-security-introduction-a859718d"
TETRAGON = "https://labs.iximiuz.com/tutorials/introduction-to-tetragon"

QUESTIONS = [
    q("sec-least", "medium", "A deploy pipeline's cloud role can create the service and also administer IAM. What do you change?", "Split the role so the pipeline can deploy and cannot edit identity.", "Add AdministratorAccess so the next failure is impossible.", "Share the role with the on-call laptop.", "Put the access key in the git repo so reviews can see it.", "The pipeline should be able to do the deploy and nothing that lets it grant itself more."),
    q("sec-least", "easy", "Least privilege means:", "The identity can do the task and cannot do the neighboring tasks.", "The identity is root and people promise to be careful.", "Everyone uses one shared user so the audit log is simple.", "Permissions are copied from production into development because they already work.", "Start from the calls you observed. Delete what the last month did not use."),
    q("sec-least", "hard", "A Kubernetes Role can get secrets in the namespace. The workload only needs to read a ConfigMap. What is the extra power?", "Anyone who compromises the pod can read every secret in the namespace, including ones it does not mount.", "ConfigMaps include secrets, so the Role is identical.", "get on secrets is required to mount a projected token.", "Roles cannot see secrets. That is a ClusterRole only.", "Mount the one secret. Do not grant list and get on all of them."),
    q("sec-least", "medium", "A break-glass admin account should be:", "Rare, logged, and stored offline. Not the account CI uses.", "The key in the pipeline.", "Shared in the team chat.", "Disabled MFA, so it works during an incident. That is how it gets used on a Tuesday.", "The emergency path is real. It is not the daily path."),
    q("sec-secrets", "medium", "A Kubernetes Secret mounted as a file is still weaker than a manager if:", "The manifest or etcd is readable, or RBAC is wide. Encoding is not encryption.", "The file is mode 0400 inside the pod, which makes it safe even when etcd is world-readable.", "Secrets are encrypted just because they are base64.", "The kubelet refuses to give a secret to a pod.", "Prefer a manager and a short lease. If you use a Secret, turn on encryption at rest and tight RBAC."),
    q("sec-secrets", "easy", "Where must a production password not live?", "In the image, in git, or in a chat paste.", "In a secret manager.", "In memory of the process that uses it, for as long as it must.", "In a CI secret the job injects.", "The places that get cloned and pulled are the leaks."),
    q("sec-secrets", "hard", "You rotated a key and the old one still works. What did the rotation miss?", "The second copy: an environment file, a laptop, a CI variable, or a cache.", "Rotation always revokes every copy automatically.", "Keys cannot be rotated.", "The manager keeps both forever and that is the design you cannot change.", "Find every consumer before you call it rotated. Disable the old credential and watch who breaks."),
    q("sec-secrets", "medium", "SOPS or Sealed Secrets belong in a GitOps repo because:", "The git history holds ciphertext. The cluster or the key holder decrypts it.", "The pull request shows the password so reviewers can type it.", "Git encrypts all files once you enable SOPS on the repo settings. You encrypt the file.", "They replace the need to rotate.", "Review that a secret changed. Do not review the secret.", AWESOME, "https://github.com/mozilla/sops"),
    q("sec-pki", "medium", "A certificate and a private key. Which one can you hand to a client?", "The certificate. The key stays on the server.", "Both. The client needs the key to trust you.", "Neither. Trust is a password.", "The key, but not the certificate.", "The certificate is public and names the key. The key proves you hold it. Giving away the key lets someone be you."),
    q("sec-pki", "medium", "The API server certificate expired and kubectl fails. Workloads are still serving. Why can both be true?", "Clients of the API check that certificate. The data plane does not re-check it on every packet of an existing flow.", "Workloads use the same kubectl binary, so they should have failed too.", "Expired certificates still verify.", "kubeconfig does not use TLS.", "Renew the control plane certs and restart the static pods. Do not reboot the whole fleet first.", IX, "https://labs.iximiuz.com/challenges/cka-practice-renew-control-plane-certificates-94a449de"),
    q("sec-pki", "easy", "A private CA is trustworthy to a client when:", "The client has that CA in its trust store. A private CA is not public trust.", "You used a long key.", "The certificate is base64.", "The hostname matches, even if the CA is unknown. Both matter.", "Install the CA where the clients are. Matching the name is the other half."),
    q("sec-pki", "hard", "mTLS between services fails after a rotation. The server cert verifies. What else rotated badly?", "The client certificate, or the server's trust of client CAs.", "DNS.", "The container image tag, which is the TLS key.", "Nothing. mTLS only checks the server.", "Both directions have a trust store. Rotate them as a pair and keep a grace period."),
    q("sec-image", "medium", "Trivy or Grype reported a critical CVE in a base image. What is the fix, not the report?", "Rebuild on a patched base, or remove the package. The scanner does not patch.", "Ignore all criticals from base images.", "Restart the container. The running layers will update.", "Delete the scanner so the CVE is gone.", "The report is a list. The release is a new digest.", AWESOME, "https://github.com/aquasecurity/trivy"),
    q("sec-image", "easy", "A smaller base image helps because:", "Fewer packages means fewer CVEs and less shell for an attacker who lands.", "Small images cannot be vulnerable.", "Distroless disables syscalls.", "Alpine is exempt from CVEs.", "Still scan it. Less is not none."),
    q("sec-image", "medium", "You scan in CI and production runs a different tag. What did the scan buy you?", "Little. You scanned bytes you did not deploy.", "A guarantee about production.", "The admission decision.", "A signature.", "Scan the digest you run, or admit only digests you have scanned."),
    q("sec-image", "hard", "A dependency scanner and an image scanner both exist. Why keep both?", "One sees the application packages. The other sees the OS packages in the image. Neither sees both reliably.", "They always report the same CVEs.", "Image scanners read package.json and nothing else.", "Dependency scanners read /var/lib/dpkg.", "Run both on the artifact you ship. Then deduplicate in the ticket, not by deleting a tool."),
    q("sec-sbom", "medium", "An SBOM is useful the morning a new CVE is published because:", "You can search what you shipped for the affected component instead of guessing.", "It patches the component.", "It replaces signing.", "It is a network policy.", "Generate it from the build and store it with the digest.", BLUE, "https://devsecblueprint.com/curriculum"),
    q("sec-sbom", "medium", "Signing an image with cosign and checking the signature at admission means:", "The cluster only runs images a key you trust has signed. A pulled tag from the internet fails closed.", "The image has no CVEs.", "The signature replaces RBAC.", "Admission is unnecessary if the registry is private.", "Verify at the cluster. A private registry still accepts whatever a stolen push credential uploads."),
    q("sec-sbom", "easy", "A signature over a tag is weaker than a signature over a digest because:", "The tag can move to unsigned bytes. The digest is the bytes.", "Digests change when the tag is pushed again, so they are less precise. The digest identifies the bytes.", "Tags are hashes.", "Signatures cannot cover a manifest.", "Sign the digest. Point the tag at it afterwards if humans need a name."),
    q("sec-sbom", "hard", "The SBOM says a library is present and the scanner did not flag it. What do you trust for 'are we running it'?", "The image or the running filesystem, not a stale SBOM from a previous build.", "The SBOM always matches production.", "The scanner, which reads the SBOM and never the image.", "Git.", "SBOMs drift when they are not produced from the shipped artifact. Regenerate from that digest."),
    q("sec-pipeline", "medium", "A pipeline that builds and deploys with the same cloud admin key means:", "Any code that runs in the build, including a dependency's install script, can deploy.", "The build is hermetic.", "Admin is required to compile.", "The key is fine if it is masked in the log.", "Separate build identity from deploy identity. The build should not be able to change production.", BLUE, "https://devsecblueprint.com/curriculum"),
    q("sec-pipeline", "hard", "pull_request_target plus a checkout of the pull request head plus secrets is:", "Untrusted code running where secrets are available.", "The safe way to test forks.", "Required for OIDC.", "Isolated by GitHub automatically.", "Run untrusted code with pull_request and no secrets. Use the privileged trigger only for code you already merged."),
    q("sec-pipeline", "easy", "Protected environments in the CI system are for:", "Requiring a reviewer and a branch rule before the production credentials are used.", "Speeding up tests.", "Storing container layers.", "Replacing code review on the application.", "The production job should be harder to start than the unit tests."),
    q("sec-pipeline", "medium", "A Dockerfile in CI does docker build with the socket of the host daemon. What did the job just get?", "Root-equivalent control of the build machine, if that daemon is rootful.", "A contained build with no access to the host.", "A rootless runtime by default.", "Read-only access to images.", "Prefer a rootless or isolated builder. The host socket is the host.", IX, DOCKER),
    q("sec-runtime", "medium", "Falco or Tetragon is in the stack so that:", "You can detect a suspicious syscall or process in a running container. It does not replace admission.", "Images are scanned.", "Git is signed.", "The API server is authenticated.", "Runtime tools see what got through. Policy should have stopped the easy cases earlier.", IX, TETRAGON),
    q("sec-runtime", "easy", "A seccomp profile of RuntimeDefault does what, compared with Unconfined?", "It blocks a default set of syscalls the runtime considers unnecessary. Unconfined allows what the kernel allows the process.", "It gives the container CAP_SYS_ADMIN.", "It is the same as privileged.", "It encrypts the root filesystem.", "Start from the runtime default. Add a custom profile only when you have measured the syscalls the app needs.", IX, SECCOMP),
    q("sec-runtime", "hard", "You applied a seccomp profile and the app breaks on one syscall. What is the repair that keeps the lockdown?", "Allow that syscall in the profile after you confirm the app needs it. Do not switch the pod to Unconfined.", "Delete seccomp from the cluster.", "Run as privileged, which is unrelated and broader.", "Disable auditd.", "The profile is a list. Open the one hole you can justify.", IX, SECCOMP),
    q("sec-runtime", "medium", "Dropping all capabilities and adding back none is a problem for an app that binds port 80 because:", "Binding a low port wants NET_BIND_SERVICE, or you can bind high and let the proxy hold 80.", "Capabilities are not checked for ports.", "Port 80 requires SYS_ADMIN.", "Dropping capabilities disables networking entirely, including high ports.", "Do not hand SYS_ADMIN to get one low port. Move the port or add the one capability.", RAE, "https://raesene.github.io/categories/capabilities/"),
    q("sec-audit", "medium", "Kubernetes audit logs are what you read to answer:", "Who called the API, and what they did. They are not the application access log.", "Which SQL query was slow.", "The node temperature.", "The image layers.", "If audit logging is off, an incident has no actor. Turn it on before you need it.", IX, PSA),
    q("sec-audit", "easy", "Pod Security audit mode differs from enforce because:", "Audit records the violation and allows the pod. Enforce rejects the new pod.", "Audit reboots the node.", "They are the same label.", "Audit deletes the namespace.", "Use audit and warn to see what would break before you enforce.", IX, PSA),
    q("sec-audit", "medium", "CloudTrail or the cloud audit log is the source for:", "Control-plane API calls in the account: who changed a security group.", "Packet payloads.", "Container stdout.", "Git commits.", "Application logs and cloud audit answer different questions. Keep both."),
    q("sec-audit", "hard", "An attacker with API access turned audit policy to None. Why is a remote copy of the log the real control?", "A log that only lives in the cluster can be edited by the person who just got in.", "Audit logs cannot be shipped.", "The API server refuses to change audit policy.", "A remote copy is slower and therefore less accurate.", "Ship the audit stream somewhere the cluster admin of the compromised cluster cannot delete."),
    q("sec-incident", "medium", "A node is suspected of a container escape. What do you do before you reimage it?", "Cordon it, isolate it, and keep a snapshot if you need to learn. Reimaging first deletes the evidence and may be right later.", "Delete the node object and forget the disk.", "Restart the kubelet and call it contained.", "Scale the deployment up on that node.", "Contain first. Decide explicitly if you are preserving evidence."),
    q("sec-incident", "easy", "Revoking the cloud keys found in a leaked repo happens:", "Before you finish the postmortem. The key is live.", "After the blog post.", "Only if the key is older than a year.", "By rotating the git history and leaving the key enabled.", "History rewrite does not disable a key. The cloud console does."),
    q("sec-incident", "hard", "A workload identity is compromised and it can read a bucket. Containment is:", "Disable that identity, block the bucket path, and look for what it already read. Restarting the pod keeps the role.", "Delete the pod. The identity is then useless. The role still exists for the next pod.", "Turn off the region.", "Ignore it if the pod is in kube-system.", "The credential is the identity, not the pod name. Revoke the role session and tighten the role."),
    q("sec-incident", "medium", "A NetworkPolicy that isolates a namespace during an incident should:", "Cut the unexpected flows and leave you a path to administer the cluster.", "Drop all cluster traffic including the node you are SSHed through, with no console.", "Be your permanent architecture with no review.", "Replace the need to rotate secrets.", "Isolation is a change. Make it one you can undo, and do not lock out the control plane."),
    q("sec-zero", "medium", "Zero trust in a platform sense means:", "The network location is not the authorization. Each call authenticates and is allowed on purpose.", "There is no firewall.", "Every packet is inspected by a human.", "VPCs are unnecessary.", "Identity, mTLS, and policy sit on top of a network that is no longer the only control."),
    q("sec-zero", "easy", "A 'trusted internal subnet' is a weak boundary because:", "A single compromised pod on that subnet can call everything that trusts the subnet.", "Subnets cannot route.", "Identity is free if the subnet matches.", "Internal traffic cannot be TLS.", "Assume the neighbor is hostile. Authenticate the call."),
    q("sec-zero", "medium", "Short-lived workload certificates are better than a long-lived token in a Secret because:", "A stolen certificate expires, and you can stop issuing the next one.", "They cannot be stolen.", "They replace authorization.", "They are stored in git.", "Pair a short lifetime with an issuer you can shut off."),
    q("sec-zero", "hard", "You terminated TLS at the edge and called the rest of the cluster trusted. What did you not get?", "Protection from anything already inside. East-west traffic is anonymous.", "A public certificate.", "A load balancer.", "DNS.", "mTLS or an equivalent identity on service calls is the inside half."),
    q("sec-threat", "medium", "Before you pick a scanner, a threat model for a cluster asks:", "What the assets are, who the attacker is, and which trust boundary they cross.", "Which vendor is in the awesome-list.", "The current CPU price.", "How many dashboards you have.", "Tools come after the abuse case. A scanner does not know what you are afraid of.", BLUE, "https://devsecblueprint.com/curriculum"),
    q("sec-threat", "easy", "A trust boundary in a platform is:", "A place where the caller's privileges change, such as the edge, the node, or the API server.", "Any microservice.", "A Grafana panel.", "A git branch.", "Draw the boundaries. The attacks you care about cross one."),
    q("sec-threat", "hard", "A container escape matters more than a bug in one app when:", "The node is shared and the escape becomes every other pod on it, plus the node role.", "The app has no data.", "You use a service mesh, which prevents kernel bugs.", "The pod has a NetworkPolicy. That does not stop a kernel exploit.", "Shared nodes share fate. The node role is the blast radius."),
    q("sec-threat", "medium", "You modeled a stolen CI token as the attacker. The useful control is:", "A token that can only deploy one environment and expires. Not a token that can also read every secret.", "A longer token so rotation is rare.", "Hiding the token in the log by not looking.", "A wiki page that says not to leak it.", "Model the token's power. Then reduce it."),
    q("sec-vault", "medium", "An OpenBao or Vault server just booted and will not serve secrets. What state is it in?", "Sealed. It needs unseal keys or a transit auto-unseal before it will decrypt.", "Empty. You must recreate every secret after each reboot.", "Healthy. A sealed server serves reads.", "Read-only.", "Unseal is the step between process-up and able-to-read.", IX, "https://labs.iximiuz.com/tutorials/openbao-vault-getting-started-e783c133"),
    q("sec-vault", "hard", "Transit auto-unseal means:", "Another Vault or OpenBao encrypts the unseal key, so operators do not type key shares at boot.", "The server never encrypts data.", "Transit replaces policies.", "Auto-unseal publishes the master key in etcd.", "You still protect the transit token. You have moved the unseal problem, not deleted it.", IX, "https://labs.iximiuz.com/tutorials/openbao-vault-auto-unseal-transit-82d2a212"),
    q("sec-vault", "easy", "A policy on a token should:", "Allow the paths that one app needs. A root token is not an application credential.", "Be root, so the app does not fail.", "Be shared across every namespace.", "Live in the container image.", "Issue a token or an AppRole for the workload. Keep root for recovery."),
    q("sec-vault", "medium", "Dynamic database credentials from Vault are better than a static password because:", "They expire, and you can tie them to the client that asked.", "They are stored in git for review.", "The database no longer authenticates.", "They cannot be revoked.", "When the lease ends, the grant ends. A static password lives until someone remembers it."),
    q("sec-bench", "medium", "kube-bench is:", "A CIS benchmark check of the cluster and node configuration. It is not a runtime intrusion detector.", "A packet capture.", "A replacement for RBAC.", "An image scanner only.", "Run it to see the control plane flags and file permissions you drifted from. Fix the findings you accept.", AWESOME, "https://github.com/aquasecurity/kube-bench"),
    q("sec-bench", "easy", "Lynis on a Linux host is for:", "A local hardening audit: sshd, permissions, and kernel settings.", "Scanning container images in a registry.", "Replacing the package manager.", "Drawing traces.", "It tells you what is weak on the box. It does not watch a running attack.", AWESOME, "https://cisofy.com/lynis/"),
    q("sec-bench", "medium", "osquery lets you:", "Ask SQL questions of the live host: processes, sockets, and files.", "Patch the kernel.", "Sign images.", "Replace Vault.", "It is how you turn 'is this binary running' into a query you can repeat.", AWESOME, "https://osquery.io/"),
    q("sec-bench", "hard", "InSpec or an equivalent compliance profile in CI means:", "The hardening rules fail the build when a machine or image drifts from them.", "The rules only print a PDF.", "Compliance replaces threat modeling.", "The profile is the same thing as a penetration test.", "Encode the rule you care about so the next image cannot quietly drop it.", AWESOME, "https://github.com/inspec/inspec"),
    q("sec-cspm", "medium", "A cloud posture tool is yelling about a public bucket and an open security group. It will not tell you:", "Whether a running container just spawned a shell. That is runtime.", "That the bucket is public.", "That a security group allows the world.", "That an access key is unused and old, if it has that check.", "CSPM looks at cloud configuration. Pair it with runtime and identity, or you only see the standing configuration.", BLUE, "https://devsecblueprint.com/curriculum"),
    q("sec-cspm", "easy", "The first public-bucket finding is fixed by:", "Blocking public access and confirming the objects are not reachable, not by muting the tool.", "Deleting the account.", "Turning the scanner off.", "Making the bucket name longer.", "Confirm with an anonymous request. The console flag and the bytes on the internet should agree."),
    q("sec-cspm", "medium", "An unused admin access key older than a year is:", "A standing credential. Disable it.", "Proof the account is healthy.", "Required for Terraform.", "A metric, not a secret.", "Old keys are how a laptop you recycled still opens the account."),
    q("sec-cspm", "hard", "The posture scan is green and an attacker is in a pod. How is that consistent?", "The cloud configuration can be tidy while a workload is compromised. Posture is not detection.", "A green scan means no process is malicious.", "CSPM reads every syscall.", "Pods cannot be compromised if buckets are private.", "Use posture for the standing mistakes and runtime for the thing happening now."),
]
